def dist(a, b):
    return max(abs(x-y) for x, y in zip(a, b))

def spatial_keep(grid, tau=8):
    kept = []
    for r, row in enumerate(grid):
        for c, cur in enumerate(row):
            near = []
            if c:
                near.append(row[c-1])
            if r:
                near.append(grid[r-1][c])
            if not near or all(dist(cur, x) > tau for x in near):
                kept.append((r, c))
    return kept

blank = (10, 10, 10)
def frame(value):
    return [[blank, blank, blank],
            [blank, blank, (value, value, value)]]

cache = {}
history = []
for grid in [frame(100), frame(105), frame(112)]:
    kept = spatial_keep(grid)
    changed = [
        (r, c) for r, c in kept
        if (r, c) not in cache
        or dist(grid[r][c], cache[(r, c)]) > 8
    ]
    for r, c in changed:
        cache[(r, c)] = grid[r][c]
    history.append((len(kept), changed))

assert history == [
    (2, [(0, 0), (1, 2)]),
    (2, []),
    (2, [(1, 2)])
]
print("kept_count and recomputed_positions:", history)
